def priority(task, state, guard=1e6, safety=0.0, age=0.1):
    est = max(task.estimated_runtime, 1e-6)
    slack = task.due - state.now - est
    wait = state.now - task.release
    if slack < -safety:
        return -guard + age * wait / est
    else:
        return -slack

