    slack = task.due - state.now - task.estimated_runtime
    if slack < 0:
        return -penalty + 1.0 / max(task.estimated_runtime, 1e-6)
    load = state.queue_len / max(state.capacity, 1e-6)
    fit = fit_bonus if task.resource_need <= state.free else 0.0
    if state.queue_len > threshold:
        denom = max(k * max(state.mean_est, 1e-6), 1e-6)
        atc = (1.0 / max(task.estimated_runtime, 1e-6)) * math.exp(-max(0.0, slack) / denom)
        return atc + fit + (m if task.tenant == 'premium' else 0.0)
    else:
        return -slack - b * task.estimated_runtime + fit + (m if task.tenant == 'premium' else 0.0)

